@Override
public boolean equals(Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || !o.getClass().equals(getClass())) {
        return false;
    }
    if (!super.equals(o)) {
        return false;
    }
    Range range = (Range) o;
    return openBottom == range.openBottom && openTop == range.openTop && Arrays.equals(bottom, range.bottom) && Arrays.equals(top, range.top);
}
